const followups = $json.body ?? [];

if (followups.length === 0) {
  return [{ json: { hasFollowups: false, message: 'No due followups today' } }];
}

const byAssignee = {};
followups.forEach(f => {
  const assignee = f.assigned_to || 'unassigned';
  if (!byAssignee[assignee]) byAssignee[assignee] = [];
  byAssignee[assignee].push(f);
});

return [{
  json: {
    hasFollowups: true,
    total_followups: followups.length,
    by_assignee: byAssignee,
    followups: followups.map(f => ({ id: f.id, title: f.title, related_type: f.related_type, due_at: f.due_at, priority: f.priority, assigned_to: f.assigned_to }))
  }
}];

if (!$json.hasFollowups) return [];

// Build email subject and body
const subject = `[Intcloudsysops] ${$json.total_followups} followup(s) due today`;
const html = `<h2>${subject}</h2>
<p>You have <strong>${$json.total_followups}</strong> action item(s) due today.</p>
<table border='1' cellpadding='10'>
<tr><th>Title</th><th>Priority</th><th>Due Date</th><th>Type</th></tr>
${$json.followups.map(f => `<tr><td>${f.title}</td><td>${f.priority || 'normal'}</td><td>${f.due_at}</td><td>${f.related_type}</td></tr>`).join('')}
</table>
<p>Log in to review and update status: <a href='https://intcloudsysops.op-sly.com'>Dashboard</a></p>`;

return [{ json: { recipients: Object.keys($json.by_assignee), subject, html } }];
